// plugins/drive/src/drive_tables.h (generated by gen_drive_tables.py, integers) against the tables te-op1-cfw's
// ports/fx/src/drive/drive.cc builds with constexpr double maths: every entry equal. Host only. `make tables`.
// The upstream file is included whole, renamed into namespace `up` (-Dop1fx=up), so its anonymous tables are visible.
//
// Copyright (C) 2026 coldsoldr. GPL-3.0-or-later with the OP-1 firmware permission.
#include <cstdint>
#include <cstdio>

#include "src/drive/drive.cc"   // upstream, with -I$(TE)
#include COOP_TABLES            // plugins/drive/src/drive_tables.h (also in namespace up: op1fx is renamed)

int main() {
  long bad = 0;
  for (int i = 0; i < 34; ++i) {
    if (up::kKTable.v[i] != up::drive_tables::kK[i]) { printf("kK[%d] %d != %d\n", i, up::kKTable.v[i], up::drive_tables::kK[i]); ++bad; }
    if (up::kInvKTable.v[i] != up::drive_tables::kInvK[i]) { printf("kInvK[%d]\n", i); ++bad; }
    if (up::kTiltTable.v[i] != up::drive_tables::kTilt[i]) { printf("kTilt[%d]\n", i); ++bad; }
  }
  for (int i = 0; i < 17; ++i)
    for (int j = 0; j < 9; ++j)
      if (up::kMakeup.v[i][j] != up::drive_tables::kMakeup[i][j]) {
        printf("kMakeup[%d][%d] %d != %d\n", i, j, up::kMakeup.v[i][j], up::drive_tables::kMakeup[i][j]);
        ++bad;
      }
  if (up::kToneK != up::drive_tables::kToneK || up::kDcK != up::drive_tables::kDcK) { printf("coefficients\n"); ++bad; }
  for (int j = 1; j <= 64; ++j)   // the count table: drive_dsp.cc's integer rounding against upstream's double
    if (up::kCount.recip[j] != (65536 + j) / (2 * j)) { printf("recip[%d]\n", j); ++bad; }
  printf("drive tables: %s (%ld differ; 34 x 3 + 153 + 2 + 64 entries)\n", bad ? "DIFFER" : "equal to upstream's constexpr", bad);
  return bad ? 1 : 0;
}
